B.bGN=new A.r("O Ache Obra pode coletar informa\xe7\xf5es fornecidas diretamente pelo usu\xe1rio durante o cadastro, utiliza\xe7\xe3o e atualiza\xe7\xe3o do perfil, incluindo nome, e-mail, telefone/WhatsApp, CPF quando necess\xe1rio, cidade, estado, categoria e perfil de uso, como Cliente, Profissional, Arquiteto ou Engenheiro.",null,B.cU,null,null,null,null,null,null,null,null)
B.af=new A.bh(null,10,null,null)
B.bA6=new A.r("Tamb\xe9m poder\xe3o ser armazenadas informa\xe7\xf5es inseridas voluntariamente pelo usu\xe1rio em seu perfil ou durante a utiliza\xe7\xe3o dos recursos disponibilizados pelo aplicativo, incluindo informa\xe7\xf5es profissionais, descri\xe7\xf5es, solicita\xe7\xf5es, publica\xe7\xf5es, imagens e outros conte\xfados necess\xe1rios ao funcionamento da plataforma.",null,B.cU,null,null,null,null,null,null,null,null)
B.bCz=new A.r("Podemos ainda coletar informa\xe7\xf5es t\xe9cnicas necess\xe1rias ao funcionamento e \xe0 seguran\xe7a do servi\xe7o, como identificadores da conta, informa\xe7\xf5es de autentica\xe7\xe3o, identificadores do dispositivo, tokens utilizados para notifica\xe7\xf5es e registros t\xe9cnicos relacionados ao funcionamento do aplicativo.",null,B.cU,null,null,null,null,null,null,null,null)
B.by0=new A.r("2. Uso das Informa\xe7\xf5es",null,B.cp,null,null,null,null,null,null,null,null)
B.bzb=new A.r("As informa\xe7\xf5es coletadas s\xe3o utilizadas para permitir o funcionamento do Ache Obra, criar e administrar contas de usu\xe1rios, disponibilizar perfis, conectar clientes a profissionais e prestadores de servi\xe7os da constru\xe7\xe3o civil, permitir a utiliza\xe7\xe3o dos recursos da plataforma e facilitar a comunica\xe7\xe3o entre os usu\xe1rios.",null,B.cU,null,null,null,null,null,null,null,null)
B.bEQ=new A.r("Os dados tamb\xe9m podem ser utilizados para autentica\xe7\xe3o, seguran\xe7a da conta, preven\xe7\xe3o de uso indevido, gerenciamento de planos e recursos contratados, atendimento ao usu\xe1rio, envio de notifica\xe7\xf5es relacionadas ao funcionamento do aplicativo e melhoria dos servi\xe7os oferecidos.",null,B.cU,null,null,null,null,null,null,null,null)
B.bF7=new A.r("3. Servi\xe7os de Terceiros",null,B.cp,null,null,null,null,null,null,null,null)
B.bFd=new A.r("Para fornecer determinadas funcionalidades, o Ache Obra utiliza servi\xe7os tecnol\xf3gicos de terceiros. Entre eles est\xe3o o Supabase, utilizado para autentica\xe7\xe3o, banco de dados e armazenamento de informa\xe7\xf5es, e servi\xe7os do Firebase, do Google, utilizados para funcionalidades como o envio de notifica\xe7\xf5es.",null,B.cU,null,null,null,null,null,null,null,null)
B.bB2=new A.r("Esses prestadores podem processar informa\xe7\xf5es estritamente necess\xe1rias para a execu\xe7\xe3o dos respectivos servi\xe7os, de acordo com suas pr\xf3prias pol\xedticas de privacidade e pr\xe1ticas de seguran\xe7a.",null,B.cU,null,null,null,null,null,null,null,null)
B.bBA=new A.r("O Ache Obra n\xe3o vende nem aluga os dados pessoais dos usu\xe1rios para terceiros e n\xe3o compartilha dados pessoais para fins de publicidade ou marketing de terceiros.",null,B.cU,null,null,null,null,null,null,null,null)
B.bBn=new A.r("4. Pagamentos e Planos",null,B.cp,null,null,null,null,null,null,null,null)
B.bFC=new A.r("O Ache Obra pode oferecer planos pagos, assinaturas e outros recursos opcionais. Quando uma compra \xe9 realizada por meio de uma loja de aplicativos ou de um provedor de pagamento autorizado, determinadas informa\xe7\xf5es da transa\xe7\xe3o s\xe3o processadas pelo respectivo provedor.",null,B.cU,null,null,null,null,null,null,null,null)
B.bEC=new A.r("O Ache Obra poder\xe1 receber e armazenar informa\xe7\xf5es necess\xe1rias para identificar e validar a compra, como produto ou plano adquirido, identificadores da transa\xe7\xe3o, situa\xe7\xe3o do pagamento e per\xedodo de validade, quando aplic\xe1vel.",null,B.cU,null,null,null,null,null,null,null,null)
B.bzE=new A.r("5. Seguran\xe7a das Informa\xe7\xf5es",null,B.cp,null,null,null,null,null,null,null,null)
B.bGQ=new A.r("Adotamos medidas t\xe9cnicas e administrativas destinadas a proteger as informa\xe7\xf5es pessoais contra acessos n\xe3o autorizados, perda, altera\xe7\xe3o, divulga\xe7\xe3o ou uso indevido.",null,B.cU,null,null,null,null,null,null,null,null)
B.bHb=new A.r("Embora sejam adotadas medidas de seguran\xe7a compat\xedveis com os servi\xe7os oferecidos, nenhum sistema eletr\xf4nico de armazenamento ou transmiss\xe3o de informa\xe7\xf5es pode garantir seguran\xe7a absoluta.",null,B.cU,null,null,null,null,null,null,null,null)
B.bAC=new A.r("6. Reten\xe7\xe3o dos Dados",null,B.cp,null,null,null,null,null,null,null,null)
B.bFk=new A.r("Os dados pessoais s\xe3o mantidos pelo per\xedodo necess\xe1rio para disponibilizar os servi\xe7os do Ache Obra, manter a conta do usu\xe1rio e cumprir as finalidades descritas nesta Pol\xedtica de Privacidade.",null,B.cU,null,null,null,null,null,null,null,null)
B.bxV=new A.r("Ap\xf3s uma solicita\xe7\xe3o de exclus\xe3o, os dados vinculados \xe0 conta ser\xe3o exclu\xeddos ou anonimizados, ressalvadas as informa\xe7\xf5es cuja conserva\xe7\xe3o seja necess\xe1ria para cumprimento de obriga\xe7\xf5es legais ou regulat\xf3rias, preven\xe7\xe3o de fraudes, seguran\xe7a, resolu\xe7\xe3o de disputas ou exerc\xedcio regular de direitos.",null,B.cU,null,null,null,null,null,null,null,null)
B.bzH=new A.r("7. Exclus\xe3o de Conta e Direitos do Usu\xe1rio (LGPD)",null,B.cp,null,null,null,null,null,null,null,null)
B.bGJ=new A.r("O usu\xe1rio poder\xe1 solicitar, nos termos da legisla\xe7\xe3o aplic\xe1vel, acesso, corre\xe7\xe3o, atualiza\xe7\xe3o ou exclus\xe3o de seus dados pessoais.",null,B.cU,null,null,null,null,null,null,null,null)
B.bFQ=new A.r("A exclus\xe3o da conta pode ser solicitada diretamente dentro do aplicativo Ache Obra, por meio da op\xe7\xe3o de exclus\xe3o de conta dispon\xedvel nas configura\xe7\xf5es ou no perfil do usu\xe1rio.",null,B.cU,null,null,null,null,null,null,null,null)
B.bD_=new A.r("O usu\xe1rio tamb\xe9m poder\xe1 solicitar a exclus\xe3o da conta por meio do suporte, enviando uma solicita\xe7\xe3o para suporte@acheobra.com.br e informando o e-mail utilizado no cadastro para que a solicita\xe7\xe3o possa ser identificada e processada.",null,B.cU,null,null,null,null,null,null,null,null)
B.bGl=new A.r("A exclus\xe3o da conta resultar\xe1 na remo\xe7\xe3o ou anonimiza\xe7\xe3o dos dados pessoais associados ao usu\xe1rio, observadas as hip\xf3teses legais que permitam ou exijam a conserva\xe7\xe3o de determinadas informa\xe7\xf5es.",null,B.cU,null,null,null,null,null,null,null,null)
B.byM=new A.r("8. Responsabilidade do Usu\xe1rio",null,B.cp,null,null,null,null,null,null,null,null)
B.bEe=new A.r("O usu\xe1rio \xe9 respons\xe1vel pelas informa\xe7\xf5es e conte\xfados que fornece ao utilizar o Ache Obra e deve evitar publicar dados pessoais sens\xedveis ou informa\xe7\xf5es de terceiros sem autoriza\xe7\xe3o.",null,B.cU,null,null,null,null,null,null,null,null)
B.bH0=new A.r("9. Altera\xe7\xf5es desta Pol\xedtica",null,B.cp,null,null,null,null,null,null,null,null)
B.bG9=new A.r("Esta Pol\xedtica de Privacidade poder\xe1 ser atualizada periodicamente para refletir altera\xe7\xf5es no aplicativo, nos servi\xe7os oferecidos ou na legisla\xe7\xe3o aplic\xe1vel. A vers\xe3o atualizada ser\xe1 disponibilizada nos canais oficiais do Ache Obra.",null,B.cU,null,null,null,null,null,null,null,null)
